import {defaults,normalize,preset,ROOM_TYPES,OBJECTS,uid,area,clamp,overlap,compute,objectRect,openingSegment} from './engine.js';
import {icon,thumb,glyph,esc,fmt,euro,plan2D,volume} from './render.js';
const $=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)];
const KEY='atelier_habitat_studio_v3';let projects={},activeId='main',s=defaults(),storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.projects){projects=saved.projects;activeId=saved.activeId;const p=projects[activeId];if(p)s=normalize(p.data);}else{const old=JSON.parse(localStorage.getItem('atelier_habitat_v2')||'null');if(old)s=normalize(old);}}catch(e){storageOK=false;}
let u={step:'layout',category:'furniture',comfort:'thermal',selected:null,inspector:'selection',view:'plan',layer:'layout',tool:'select',grid:true,snap:true,zoom:1,panX:0,panY:0,yaw:-28,query:''};let past=[],future=[],drag=null,raf=0,toastTimer,baseBounds=null,viewBox=null;
const get=path=>path.split('.').reduce((o,k)=>o?.[k],s);
const set=(path,v)=>{const p=path.split('.'),k=p.pop();p.reduce((o,k)=>o[k],s)[k]=v;};
const snap=n=>u.snap?Math.round(n*10)/10:n;
const smallIcon=k=>`<span data-icon="${k}">${icon(k)}</span>`;
function paintIcons(){for(const e of $$('[data-icon]'))e.innerHTML=icon(e.dataset.icon);}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3100);}
function save(){try{projects[activeId]={data:s,updated:new Date().toISOString()};localStorage.setItem(KEY,JSON.stringify({activeId,projects}));storageOK=true;}catch(e){storageOK=false;}$('#save-state').textContent=storageOK?'Enregistré sur cet appareil':'Sauvegarde indisponible · exportez le projet';}
function action(fn,fit=false){const before=JSON.stringify(s);fn();s=normalize(s);if(before!==JSON.stringify(s)){past.push(before);if(past.length>70)past.shift();future=[];}save();render(fit);}
function undo(){if(!past.length)return;future.push(JSON.stringify(s));s=normalize(JSON.parse(past.pop()));save();validateSelection();render(true);toast('Modification annulée');}
function redo(){if(!future.length)return;past.push(JSON.stringify(s));s=normalize(JSON.parse(future.pop()));save();validateSelection();render(true);toast('Modification rétablie');}
function validateSelection(){if(!u.selected)return;if(u.selected.type==='zone')return;const list=u.selected.type==='room'?s.rooms:u.selected.type==='object'?s.objects:s.openings;if(!list.some(o=>o.id===u.selected.id))u.selected=null;}
function current(){if(!u.selected)return null;return u.selected.type==='zone'?s.zone:(u.selected.type==='room'?s.rooms:u.selected.type==='object'?s.objects:s.openings).find(q=>q.id===u.selected.id);}
function selectedName(){const o=current();return !o?'':u.selected.type==='zone'?'Module habitable':u.selected.type==='room'?o.name:u.selected.type==='object'?OBJECTS[o.kind].name:({window:'Fenêtre',door:'Porte',bay:'Porte d’atelier'})[o.kind];}
function field(label,path,unit='',step='.1',min=0,max='',value=undefined){return `<label class="field"><span>${label}</span><div class="input-wrap"><input type="number" ${path.startsWith('@')?`data-entity-field="${path.slice(1)}"`:`data-path="${path}"`} value="${esc(value===undefined?get(path):value)}" min="${min}" ${max!==''?`max="${max}"`:''} step="${step}" aria-label="${label}"><i>${unit}</i></div></label>`;}
function select(label,path,options,value=undefined){const v=value===undefined?get(path):value;return `<label class="field"><span>${label}</span><select ${path.startsWith('@')?`data-entity-field="${path.slice(1)}"`:`data-path="${path}"`} aria-label="${label}">${options.map(([k,t])=>`<option value="${k}" ${String(k)===String(v)?'selected':''}>${t}</option>`).join('')}</select></label>`;}
const heading=(k,t,desc='')=>`<button class="icon-btn drawer-close" data-close-drawer aria-label="Fermer">${icon('close')}</button><div class="kicker">${k}</div><h2>${t}</h2>${desc?`<p class="intro">${desc}</p>`:''}`;
const note=(t,desc,k='info')=>`<div class="info-note">${icon(k)}<div><strong>${t}</strong>${desc}</div></div>`;
const section=(name,detail='')=>`<div class="section-label">${name}${detail?`<small>${detail}</small>`:''}</div>`;
const line=(label,val,cls='')=>`<div class="line-row ${cls}"><span>${label}</span><strong>${val}</strong></div>`;
function roomList(){return `<div class="room-list">${s.rooms.map(r=>`<button class="list-item ${u.selected?.type==='room'&&u.selected.id===r.id?'active':''}" data-select="room:${r.id}"><i style="background:${ROOM_TYPES[r.type].accent}"></i>${esc(r.name)}<small>${fmt(area(r))} m²</small></button>`).join('')||'<div class="empty">Ajoutez votre première pièce.</div>'}</div>`;}
function renderCatalog(){const C=compute(s);let h='';
if(u.step==='layout'){h+=heading('FAITES PLACE À VOS IDÉES','Aménager votre espace','Choisissez un élément, puis déplacez-le sur le plan.');h+=`<div class="segmented catalog-tabs"><button data-category="rooms" class="${u.category==='rooms'?'active':''}">Pièces</button><button data-category="furniture" class="${u.category==='furniture'?'active':''}">Mobilier</button></div><label class="search">${icon('search')}<input id="catalog-search" placeholder="Rechercher un élément…" value="${esc(u.query)}" aria-label="Rechercher un élément"></label><div id="catalog-items">${catalogItems()}</div>`;h+=note('À vous de jouer','Glissez depuis le catalogue ou touchez un élément pour l’ajouter. Les dimensions restent modifiables.','cursor');}
if(u.step==='building'){h+=heading('LE POINT DE DÉPART','Votre bâtiment','Un petit habitat, un grand terrain de jeu. Définissez l’enveloppe de votre projet.');h+=section('Dimensions intérieures');h+=`<div class="fields">${field('Largeur','building.w','m','.5',5,100)}${field('Longueur','building.l','m','.5',5,100)}${field('Hauteur libre','building.h','m','.1',2.4,20)}${field('Prix d’achat','building.price','€',1000,0)}</div>`;h+=section('Le module habitable',`${fmt(C.home)} m²`);h+=`<div class="fields">${field('Largeur','zone.w','m','.1',2,s.building.w)}${field('Longueur','zone.l','m','.1',2,s.building.l)}${field('Plafond','zone.h','m','.1',2,s.building.h)}${field('Nord du plan','orientation','°',5,0,359)}${field('Position X','zone.x','m','.1',0,s.building.w-s.zone.w)}${field('Position Y','zone.y','m','.1',0,s.building.l-s.zone.l)}</div><button class="btn full" data-select="zone:zone">${icon('cursor')}Déplacer le module sur le plan</button>`;h+=section('Partir d’un scénario');h+=`<div class="preset-grid">${[100,150,200].map(x=>`<button data-preset="${x}" class="${Math.abs(C.total-x)<.1?'active':''}"><strong>${x}</strong>m²</button>`).join('')}</div>`;h+=note('Votre point de départ','Le scénario d’origine conserve 56 m² de logement et 94 m² d’atelier. Les mesures décrivent des surfaces brutes, hors épaisseur des cloisons.','ruler');}
if(u.step==='openings'){h+=heading('OUVREZ LES PERSPECTIVES','Portes & fenêtres','Des ouvertures à la bonne taille, sur la bonne façade.');h+=`<div class="catalog-grid">${[['window','Fenêtre','1,20 × 1,20 m','window'],['door','Porte','0,90 × 2,10 m','door'],['bay','Porte d’atelier','3 × 3 m','building']].map(([k,t,d,i])=>`<button class="catalog-card" data-add-opening="${k}"><span class="thumb">${icon(i)}</span><span class="card-name">${t}</span><span class="card-size">${d}</span><span class="card-plus">${icon('plus')}</span></button>`).join('')}</div>`;h+=section('Ouvertures dessinées',String(s.openings.length));h+=`<div class="room-list">${s.openings.map(o=>`<button class="list-item ${u.selected?.id===o.id?'active':''}" data-select="opening:${o.id}">${icon(o.kind==='window'?'window':'door')}<span>${o.kind==='window'?'Fenêtre':o.kind==='door'?'Porte':'Porte atelier'}<small>${{north:'Haut',south:'Bas',west:'Gauche',east:'Droite'}[o.wall]} · ${o.host==='zone'?'module':'bâtiment'}</small></span><small>${fmt(o.w)} m</small></button>`).join('')}</div>`;h+=note('La lumière vient de dehors','Seules les fenêtres réellement en façade du logement alimentent son repère de vitrage. Une fenêtre vers l’atelier ne compte pas.','sun');}
if(u.step==='comfort'){h+=heading('BIEN VIVRE À L’INTÉRIEUR','Le confort, en clair','Ajustez vos hypothèses et visualisez leur effet sur le projet.');h+=`<div class="segmented catalog-tabs"><button data-comfort="thermal" class="${u.comfort==='thermal'?'active':''}">${icon('snow')}Isolation</button><button data-comfort="light" class="${u.comfort==='light'?'active':''}">${icon('sun')}Lumière</button></div>`;
if(u.comfort==='thermal'){h+=`<div class="fields one">${select('Volume à isoler','thermal.scope',[['home','Module habitable'],['all','Bâtiment entier']])}${select('Conductivité de l’isolant (λ)','thermal.lambda',[[.035,'0,035 W/m·K — laine courante'],[.032,'0,032 W/m·K — laine performante'],[.04,'0,040 W/m·K — laine standard'],[.022,'0,022 W/m·K — PIR / PUR']])}</div>`;h+=section('Épaisseur de l’isolant');h+=`<div class="fields">${field('Murs','thermal.wall','mm',10,0,500)}${field('Plafond','thermal.roof','mm',10,0,600)}${field('Sol','thermal.floor','mm',10,0,500)}${field('Marge de coupe','thermal.waste','%',1,0,50)}</div>`;h+=section('Coût des matériaux','hors pose');h+=`<div class="fields">${field('Isolant murs','thermal.wallprice','€/m²',1,0)}${field('Isolant plafond','thermal.roofprice','€/m²',1,0)}${field('Isolant sol','thermal.floorprice','€/m²',1,0)}</div>`;h+=`<details><summary>Hypothèses thermiques avancées</summary><div class="fields">${field('Intérieur','thermal.inside','°C',1,5,30)}${field('Extérieur','thermal.outside','°C',1,-30,25)}${field('Atelier non chauffé','thermal.shop','°C',1,-15,25)}${field('Sol / terre','thermal.ground','°C',1,-5,25)}${field('Renouvellement d’air','thermal.air','vol/h','.1',0,5)}${field('Uw fenêtres','thermal.ug','W/m²K','.1',.3,7)}${field('Ud portes','thermal.ud','W/m²K','.1',.3,7)}</div></details>`;h+=note('Mieux isoler, moins perdre','R = épaisseur ÷ λ. Le bilan distingue les murs extérieurs et les parois donnant sur l’atelier.','snow');}
else{h+=section('Éclairage du logement');h+=`<div class="fields">${field('Flux par luminaire','light.lumens','lm',100,100,50000)}${field('Puissance unitaire','light.watt','W',1,1,1000)}</div>`;h+=section('Éclairage de l’atelier');h+=`<div class="fields">${field('Éclairement visé','light.shoplux','lux',50,50,2000)}${field('Flux par luminaire','light.shoplumens','lm',100,100,100000)}${field('Puissance unitaire','light.shopwatt','W',1,1,3000)}${field('Allumé par jour','light.hours','h','.5',0,24)}</div>`;h+=section('Calcul & lumière naturelle');h+=`<div class="fields">${field('Facteur d’utilisation','light.factor','','.05',.1,1)}${field('Prix d’électricité','light.kwhPrice','€/kWh','.01',0,3)}${field('Vitrage / surface cible','light.target','%','.5',1,50)}</div>`;h+=`<button class="btn full" data-go="openings">${icon('window')}Modifier les fenêtres</button>`;h+=note('Chaque pièce a son besoin','Sélectionnez une pièce pour régler ses lux. Les points lumineux du plan représentent la quantité estimée, sans étude photométrique.','lightbulb');}}
if(u.step==='budget'){h+=heading('LE PROJET, CÔTÉ CHIFFRES','Un budget maîtrisé','Des hypothèses transparentes, à ajuster avec vos devis.');h+=section('Acquisition');h+=`<div class="fields">${field('Prix d’achat','building.price','€',1000,0)}${field('Frais d’acquisition','budget.fees','%',.5,0,20)}</div>`;h+=section('Hypothèses de travaux');h+=`<div class="fields">${field('Réseaux & finitions','budget.fitout','€/m²',10,0,5000)}${field('Ossature & cloisons','budget.partition','€/m²',5,0,1000)}${field('Fenêtres','budget.glazing','€/m²',50,0,5000)}${field('Portes & accès','budget.door','€/m²',20,0,5000)}${field('Provision imprévus','budget.contingency','%',1,0,50)}</div>`;h+=section('Coût des isolants');h+=`<div class="fields">${field('Murs','thermal.wallprice','€/m²',1,0)}${field('Plafond','thermal.roofprice','€/m²',1,0)}${field('Sol','thermal.floorprice','€/m²',1,0)}</div>`;h+=note('Vos chiffres, vos décisions','Ces montants sont des valeurs de simulation modifiables. Le mobilier peut être chiffré élément par élément. Achat, travaux et imprévus sont séparés.','wallet');h+=`<button class="btn full" data-action="print">${icon('file')}Imprimer le récapitulatif</button>`;}
$('#catalog-content').innerHTML=h;$('#object-count').textContent=`${s.rooms.length} pièces · ${s.objects.length} éléments · ${s.openings.length} ouvertures`;
}
function catalogItems(){const q=u.query.toLocaleLowerCase('fr');const filtered=(entries)=>entries.filter(([,k])=>k.name.toLocaleLowerCase('fr').includes(q));const cards=(entries,room=false)=>`<div class="catalog-grid">${entries.map(([key,k])=>`<button class="catalog-card" draggable="true" data-add-${room?'room':'object'}="${key}" title="Ajouter : ${k.name}"><span class="thumb">${thumb(key,room)}</span><span class="card-name">${k.name}</span><span class="card-size">${fmt(k.w)} × ${fmt(k.l)} m</span><span class="card-plus">${icon('plus')}</span></button>`).join('')}</div>`;
if(u.category==='rooms')return section('Les pièces du logement')+cards(filtered(Object.entries(ROOM_TYPES)),true)+section('Dans votre plan',`${s.rooms.length} pièces`)+roomList();const home=filtered(Object.entries(OBJECTS).filter(([,k])=>!k.shop)),shop=filtered(Object.entries(OBJECTS).filter(([,k])=>k.shop));return (home.length?section('À la maison',`${home.length} éléments`)+cards(home):'')+(shop.length?section('Côté atelier',`${shop.length} éléments`)+cards(shop):'')+(!home.length&&!shop.length?'<p class="empty">Aucun élément trouvé.</p>':'');}
function thermalCard(C){return `<div class="summary-card"><h3>Une enveloppe confortable${icon('snow')}</h3><div class="thermal-bars">${[['Murs',C.Rs[0],3.7],['Plafond',C.Rs[1],6],['Sol',C.Rs[2],3]].map(([t,r,target])=>`<div class="thermal-row"><div><span>${t}</span><b class="${r>=target?'good':'warning'}">R ${fmt(r,1)}</b></div><div class="progress"><i style="width:${Math.min(100,r/target*100)}%"></i></div></div>`).join('')}</div><div class="subtle-text">Repères de conception : R 3,7 / 6 / 3, modifiables en ajustant l’épaisseur.</div>${line('Puissance perdue estimée',`${fmt(C.heat/1000,2)} kW`)}<p class="subtle-text">Estimation stationnaire, hors ponts thermiques. Ce résultat n’est pas un dimensionnement de chauffage.</p></div>`;}
function budgetCard(C){return `<div class="summary-card"><h3>Budget global estimé${icon('wallet')}</h3><div class="big-price">${euro(C.budget)}</div><div class="subtle-text">Achat + frais + aménagement + imprévus</div><div class="budget-stack">${C.lots.map(l=>`<span style="width:${l.value/Math.max(1,C.works)*100}%;background:${l.color}" title="${l.name}"></span>`).join('')}</div>${line('Achat & frais',euro(s.building.price+C.fees))}${line('Travaux & équipements',euro(C.works))}${line('Provision imprévus',euro(C.contingency))}<button class="mini-btn" data-go="budget">Ajuster les hypothèses</button></div>`;}
function overview(C){return `<div class="summary-card"><h3>Le bon équilibre${icon('layout')}</h3><div class="two-numbers"><div><strong>${fmt(C.home)}<small> m²</small></strong><div class="subtle-text">pour vivre</div></div><div><strong>${fmt(C.free)}<small> m²</small></strong><div class="subtle-text">pour créer</div></div></div><div class="progress"><i style="width:${C.home/C.total*100}%"></i></div><div class="subtle-text">${fmt(C.home/C.total*100,0)} % du bâtiment aménagé</div></div><div class="summary-card"><h3>La lumière naturelle${icon('sun')}</h3>${line('Fenêtres côté logement',`${fmt(C.windows,2)} m²`)}${line('Objectif de vitrage',`${fmt(C.home*s.light.target/100,2)} m²`)}<div class="progress"><i style="width:${Math.min(100,C.windows/(C.home*s.light.target/100)*100)}%;background:${C.windows/C.home>=s.light.target/100?'#9db583':'#c6b482'}"></i></div><div class="subtle-text">${fmt(C.windows/C.home*100,1)} % vitrés · cible de conception ${fmt(s.light.target)} %</div></div>${u.step==='comfort'&&u.comfort==='thermal'?thermalCard(C):''}${budgetCard(C)}${u.step!=='comfort'?`<button class="btn full" data-go="comfort">${icon('snow')}Explorer le confort</button>`:''}`;}
function renderInspector(){const C=compute(s),o=current();let h=`<div class="inspector-title"><h2>${o?'Votre sélection':u.step==='budget'?'Votre estimation':'Vue d’ensemble'}</h2><button class="icon-btn drawer-close" data-close-drawer aria-label="Fermer">${icon('close')}</button>${!o?'<span class="mini-tag">EN DIRECT</span>':''}</div>`;
if(o)h+=`<div class="segmented inspector-tabs"><button data-inspector="selection" class="${u.inspector==='selection'?'active':''}">Réglages</button><button data-inspector="overview" class="${u.inspector==='overview'?'active':''}">Bilan du projet</button></div>`;
if(o&&u.inspector==='selection'){const type=u.selected.type;h+=`<div class="selection-chip"><i style="background:${type==='room'?ROOM_TYPES[o.type].accent:'#91a779'}"></i>${esc(selectedName())}${type!=='opening'?`<small>${fmt(area(o))} m²</small>`:''}</div>`;
if(type==='room'){h+=`<label class="field text-field"><span>Nom de la pièce</span><input data-entity-field="name" value="${esc(o.name)}" maxlength="50"></label><div class="fields">${field('Largeur','@w','m','.1',.6,s.zone.w,o.w)}${field('Longueur','@l','m','.1',.6,s.zone.l,o.l)}${field('Position X','@x','m','.1',0,s.zone.w-o.w,o.x)}${field('Position Y','@y','m','.1',0,s.zone.l-o.l,o.y)}</div>`;h+=section('Ambiance & usage');h+=`<div class="fields one">${select('Type de pièce','@type',Object.entries(ROOM_TYPES).map(([k,v])=>[k,v.name]),o.type)}${field('Éclairement visé','@lux','lux',50,50,2000,o.lux)}</div>`;const r=C.roomRows.find(r=>r.id===o.id);h+=section('Lumière de cette pièce');h+=line('Points lumineux estimés',`${r.fixtures} × ${fmt(s.light.lumens,0)} lm`)+line('Vitrage en façade',`${fmt(r.glass,2)} m²`)+line('Ratio de vitrage',`${fmt(r.glass/r.area*100,1)} %`);h+=`<p class="subtle-text">Le vitrage est attribué selon sa position réelle, sur une façade extérieure de cette pièce.</p>`;}
if(type==='object'){const parent=s.rooms.find(r=>r.id===o.roomId)||s.building;h+=`<div class="fields">${field('Largeur','@w','m','.05',.15,parent.w,o.w)}${field('Profondeur','@l','m','.05',.15,parent.l,o.l)}${field('Position X','@x','m','.05',0,parent.w-o.w,o.x)}${field('Position Y','@y','m','.05',0,parent.l-o.l,o.y)}</div>`;h+=section('Emplacement');h+=`<div class="fields one">${select('Rattacher à','@roomId',[["","Bâtiment / atelier"],...s.rooms.map(r=>[r.id,r.name])],o.roomId||'')}${field('Coût de cet élément','@price','€',10,0,1e6,o.price??OBJECTS[o.kind].price)}</div><p class="subtle-text" style="margin-top:10px">Les cotes suivent l’encombrement vu du dessus. Glissez l’objet vers une autre pièce pour le déplacer.</p>`;}
if(type==='opening'){h+=`<div class="fields one">${select('Mur porteur de l’ouverture','@host',[['building','Enveloppe du bâtiment'],['zone','Module habitable']],o.host)}${select('Côté du plan','@wall',[['north','Haut du plan'],['east','Droite du plan'],['south','Bas du plan'],['west','Gauche du plan']],o.wall)}</div>`;h+=section('Dimensions de l’ouverture');h+=`<div class="fields">${field('Largeur','@w','m','.1',.3,['north','south'].includes(o.wall)?s[o.host].w:s[o.host].l,o.w)}${field('Hauteur','@h','m','.1',.3,s[o.host].h,o.h)}${field('Distance depuis l’angle','@offset','m','.1',0,100,o.offset)}</div>`;h+=note('Une position précise','La distance est mesurée depuis le haut ou la gauche du mur. L’orientation du nord se règle dans Bâtiment.','ruler');}
if(type==='zone'){h+=`<div class="fields">${field('Largeur','zone.w','m','.1',2,s.building.w)}${field('Longueur','zone.l','m','.1',2,s.building.l)}${field('Plafond','zone.h','m','.1',2,s.building.h)}${field('Position X','zone.x','m','.1',0,s.building.w-s.zone.w)}${field('Position Y','zone.y','m','.1',0,s.building.l-s.zone.l)}</div>`;h+=note('Votre maison dans le hangar','Le mobilier et les pièces suivent le module. En réduisant sa taille, vérifiez les chevauchements signalés.','home');}
if(type!=='zone')h+=`<div class="form-actions">${type==='opening'?'':`<button class="btn" data-action="rotate">${icon('rotate')}Tourner</button>`}<button class="btn" data-action="duplicate">${icon('copy')}Dupliquer</button></div><button class="btn danger full" data-action="delete">${icon('trash')}Retirer ${type==='room'?'la pièce':type==='object'?'l’élément':'l’ouverture'}</button>`;
}else if(u.step==='budget'){h+=`<div class="kicker">ENVELOPPE GLOBALE</div><div class="big-price">${euro(C.budget)}</div><p class="subtle-text">${fmt(C.total)} m² dont ${fmt(C.home)} m² habités · hypothèses modifiables</p><hr class="section-divider">${line('Achat',euro(s.building.price))}${line(`Frais (${fmt(s.budget.fees)} %)`,euro(C.fees))}<hr class="section-divider"><h3>Travaux & équipements</h3><div class="budget-stack">${C.lots.map(l=>`<span style="width:${l.value/Math.max(1,C.works)*100}%;background:${l.color}"></span>`).join('')}</div>${C.lots.map(l=>`<div class="cost-line" title="${esc(l.note)}"><i style="background:${l.color}"></i><span>${l.name}</span><strong>${euro(l.value)}</strong></div>`).join('')}${line('Sous-total travaux',euro(C.works),'total')}${line(`Imprévus (${fmt(s.budget.contingency)} %)`,euro(C.contingency))}${line('Travaux avec réserve',euro(C.works+C.contingency),'total')}<p class="subtle-text" style="margin-top:18px">Hors étude de structure, réfection du bâtiment, raccordements extérieurs, taxes et autorisations. Les prix ne constituent pas des devis.</p>`;
}else if(u.step==='comfort'){if(u.comfort==='thermal'){h+=thermalCard(C)+`<div class="summary-card"><h3>Quantités à prévoir${icon('ruler')}</h3>${line('Murs à isoler',`${fmt(C.walls)} m²`)}${line('Dont côté atelier',`${fmt(C.internalWalls)} m²`)}${line('Plafond / toiture',`${fmt(C.roof)} m²`)}${line('Sol',`${fmt(C.roof)} m²`)}${line('Isolants avec coupe',euro(C.materials),'total')}<div class="subtle-text">Surfaces nettes, ouvertures retirées. Achats = surfaces × (1 + ${fmt(s.thermal.waste)} %).</div></div>`;}else{h+=`<div class="summary-card"><h3>Éclairer chaque usage${icon('lightbulb')}</h3>${line('Points dans le logement',String(C.homeFixtures))}${line('Points dans l’atelier',String(C.shopFixtures))}${line('Puissance installée',`${fmt(C.watts,0)} W`)}${line('Énergie / an',`${fmt(C.kwh,0)} kWh`)}${line('Coût simulé / an',euro(C.energy),'total')}<div class="subtle-text">${fmt(s.light.hours)} h/jour, 365 jours/an, sans réduction liée au soleil.</div></div><div class="summary-card"><h3>Pièce par pièce${icon('room')}</h3>${C.roomRows.map(r=>line(r.name,`${r.fixtures} points`)).join('')}${C.spare>.01?line('Zone non affectée',`${fmt(C.spare)} m² · 150 lux`):''}</div>`;}h+=`<button class="btn full" data-action="overview">${icon('eye')}Voir le bilan global</button>`;}
else h+=overview(C);
$('#inspector-content').innerHTML=h;}
function renderMetrics(){const C=compute(s);$('#metrics').innerHTML=[['building','Surface totale',C.total],['home','Habitation',C.home],['layout','Espace libre',C.free]].map(([k,t,v])=>`<div class="metric"><div class="metric-icon">${icon(k)}</div><div><span class="metric-label">${t}</span><strong>${fmt(v)}<small>m²</small></strong></div></div>`).join('');const warn=warnings(C);$('#inline-status').classList.toggle('has-warning',warn.length>0);$('#inline-status').textContent=warn[0]||`${s.rooms.length} pièces · ${C.spare>.05?fmt(C.spare)+' m² à répartir':'un espace bien réparti'}`;$('#inline-status').title=warn.join('\n');$('#print-summary').innerHTML=`<div class="print-grid"><section><h3>Isolation & lumière</h3>${line('Surface murs',`${fmt(C.walls)} m²`)}${line('Plafond et sol',`${fmt(C.roof)} m² chacun`)}${line('R murs / plafond / sol',C.Rs.map(r=>fmt(r,2)).join(' / '))}${line('Vitrage logement',`${fmt(C.windows,2)} m²`)}${line('Luminaires logement / atelier',`${C.homeFixtures} / ${C.shopFixtures}`)}</section><section><h3>Estimation du projet</h3>${line('Achat & frais',euro(s.building.price+C.fees))}${C.lots.map(l=>line(l.name,euro(l.value))).join('')}${line('Imprévus',euro(C.contingency))}${line('Total',euro(C.budget),'total')}</section></div><p class="subtle-text" style="margin-top:20px">Avant-projet · coûts indicatifs modifiables · surfaces brutes hors épaisseur des cloisons · hors étude de structure, réfection du bâtiment et raccordements extérieurs. Déperditions estimées hors ponts thermiques. Atelier Habitat — ${new Date().toLocaleDateString('fr-FR')}</p>`;}
function warnings(C){const w=[];if(C.pairs.length)w.push(`${C.pairs.length} chevauchement${C.pairs.length>1?'s':''} entre pièces — à ajuster`);if(C.openingPairs.length)w.push(`${C.openingPairs.length} chevauchement entre ouvertures`);if(C.unexposed)w.push(`${C.unexposed} fenêtre${C.unexposed>1?'s':''} sans accès direct à l’extérieur`);if(C.windows/C.home<s.light.target/100)w.push(`Lumière naturelle : ${fmt(C.home*s.light.target/100-C.windows,1)} m² de vitrage sous votre cible`);return w;}
function renderSelectionBar(){const o=current(),bar=$('#selection-bar');bar.hidden=!o;if(!o)return;const type=u.selected.type;bar.innerHTML=`<span class="selection-name">${esc(selectedName())}</span><button class="icon-btn" data-action="inspect" title="Régler cet élément" aria-label="Régler cet élément">${icon('ruler')}</button>${type!=='zone'?`<span class="divider"></span>${type!=='opening'?`<button class="icon-btn" data-action="rotate" title="Tourner (R)" aria-label="Tourner">${icon('rotate')}</button>`:''}<button class="icon-btn" data-action="duplicate" title="Dupliquer (Ctrl D)" aria-label="Dupliquer">${icon('copy')}</button><button class="icon-btn" data-action="delete" title="Supprimer" aria-label="Supprimer">${icon('trash')}</button>`:''}`;}
function applyViewBox(bounds){if(bounds)baseBounds=bounds;if(!baseBounds)return;viewBox={x:baseBounds.x+baseBounds.w/2-baseBounds.w/u.zoom/2+u.panX,y:baseBounds.y+baseBounds.h/2-baseBounds.h/u.zoom/2+u.panY,w:baseBounds.w/u.zoom,h:baseBounds.h/u.zoom};$('#plan').setAttribute('viewBox',`${viewBox.x} ${viewBox.y} ${viewBox.w} ${viewBox.h}`);$('#zoom-value').textContent=`${Math.round(u.zoom*100)} %`;}
function renderPlan(fit=false){if(fit){u.panX=0;u.panY=0;u.zoom=1;}if(u.view==='volume'){const v=volume(s,u);$('#plan').innerHTML=v.markup;applyViewBox(v.bounds);}else{$('#plan').innerHTML=plan2D(s,u);applyViewBox({x:-1.15,y:-1.2,w:s.building.w+2.3,h:s.building.l+2.4});}$('#north').style.transform=`rotate(${s.orientation}deg)`;$('#board').classList.toggle('pan',u.tool==='pan');$('#board-subtitle').textContent=u.view==='volume'?'Vue en volume · toiture retirée':'Cotes intérieures · mètres';$('#view-hint').textContent=u.view==='volume'?'Glissez pour faire pivoter la vue':'Cliquez sur une pièce pour la modifier';$('#grid-toggle').classList.toggle('active',u.grid);$('#snap-toggle').classList.toggle('active',u.snap);$('#layer-name').textContent={layout:'Aménagement',light:'Lumière',thermal:'Isolation'}[u.layer];$$('[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===u.view));$$('[data-tool]').forEach(e=>e.classList.toggle('active',e.dataset.tool===u.tool));renderSelectionBar();}
function render(fit=false){validateSelection();$('#project-name').textContent=s.name;$('#undo').innerHTML=icon('undo');$('#redo').innerHTML=icon('redo');$('#brand-icon').innerHTML=icon('building');$('#undo').disabled=!past.length;$('#redo').disabled=!future.length;$$('[data-step]').forEach(e=>e.classList.toggle('active',e.dataset.step===u.step));renderCatalog();renderInspector();renderMetrics();renderPlan(fit);paintIcons();}
function closeDrawers(){ $('.app').classList.remove('show-catalog','show-inspector'); }
function go(step){u.step=step;u.selected=null;u.inspector='selection';if(step==='comfort')u.layer=u.comfort;if(step==='layout'||step==='building'||step==='openings')u.layer='layout';render();if(innerWidth<=650){$('.app').classList.remove('show-inspector');$('.app').classList.add('show-catalog');}}
function choose(type,id,open=false){u.selected={type,id};u.inspector='selection';renderInspector();renderSelectionBar();renderPlan();if(open&&innerWidth<=900){$('.app').classList.remove('show-catalog');$('.app').classList.add('show-inspector');}}
function openModal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-modal-close aria-label="Fermer">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
let confirmation=null;
function confirmAction(title,body,fn){confirmation=fn;openModal(title,`<p>${body}</p><div class="modal-actions"><button class="btn" data-modal-close>Conserver</button><button class="btn primary" data-confirm>Continuer</button></div>`);}
function addRoom(kind,pos=null){const k=ROOM_TYPES[kind];if(!k)return;const w=Math.min(k.w,s.zone.w),l=Math.min(k.l,s.zone.l);let found=null;for(let y=0;y<=s.zone.l-l+.01&&!found;y+=.25)for(let x=0;x<=s.zone.w-w+.01;x+=.25)if(!s.rooms.some(r=>overlap({x,y,w,l},r))){found={x,y};break;}if(pos)found={x:clamp(snap(pos.x-s.zone.x-w/2),0,s.zone.w-w),y:clamp(snap(pos.y-s.zone.y-l/2),0,s.zone.l-l)};const free=!!found;const p=found||{x:clamp((s.zone.w-w)/2,0,s.zone.w-w),y:clamp((s.zone.l-l)/2,0,s.zone.l-l)};const id=uid();action(()=>s.rooms.push({id,type:kind,name:k.name,...p,w,l,lux:k.lux}));choose('room',id);closeDrawers();toast(free?`${k.name} ajouté(e)`:'Pièce ajoutée : ajustez les chevauchements ou agrandissez le module.');}
function addObject(kind,pos=null){const k=OBJECTS[kind];if(!k)return;let r=null;if(!k.shop){if(u.selected?.type==='room')r=current();else if(u.selected?.type==='object')r=s.rooms.find(r=>r.id===current().roomId);r=r||s.rooms.find(r=>r.type===({bed:'bed',wardrobe:'bed',kitchen:'kitchen',island:'kitchen',fridge:'kitchen',shower:'bath',wc:'bath',sink:'bath',desk:'office'}[kind]||'living'))||s.rooms[0];}if(pos)r=s.rooms.find(r=>pos.x>=s.zone.x+r.x&&pos.x<=s.zone.x+r.x+r.w&&pos.y>=s.zone.y+r.y&&pos.y<=s.zone.y+r.y+r.l);const p=r||s.building;const w=Math.min(k.w,p.w),l=Math.min(k.l,p.l);let spot=null;if(pos){spot={x:clamp(snap(pos.x-(r?s.zone.x+r.x:0)-w/2),0,p.w-w),y:clamp(snap(pos.y-(r?s.zone.y+r.y:0)-l/2),0,p.l-l)};}else{for(let y=.15;y<=p.l-l+.01&&!spot;y+=.2)for(let x=.15;x<=p.w-w+.01;x+=.2){const test={x,y,w,l};if(!s.objects.filter(o=>o.roomId===(r?.id||null)).some(o=>overlap(test,o))&& (r||!overlap(test,s.zone))){spot={x:Math.round(x*100)/100,y:Math.round(y*100)/100};break;}}}spot=spot||{x:Math.max(0,(p.w-w)/2),y:Math.max(0,(p.l-l)/2)};const id=uid();action(()=>s.objects.push({id,kind,roomId:r?.id||null,...spot,w,l,rotation:0,price:k.price}));choose('object',id);closeDrawers();toast(`${k.name} ajouté(e) — glissez pour le placer`);}
function addOpening(kind){const id=uid(),w=kind==='window'?1.2:kind==='door'?.9:3,h=kind==='window'?1.2:kind==='door'?2.1:3;const o={id,kind,host:kind==='bay'?'building':'zone',wall:kind==='bay'?'east':'north',offset:0,w,h};let spot=null;for(const wall of (kind==='bay'?['east','south','north','west']:['north','west','south','east'])){const p=s[o.host],len=['north','south'].includes(wall)?p.w:p.l;for(let offset=.3;offset<=len-w-.1;offset+=.1){const candidate={...o,wall,offset};const a=openingSegment(s,candidate);if(kind==='window'&&o.host==='zone'&& !(Math.abs(a.x1)<.01||Math.abs(a.x1-s.building.w)<.01||Math.abs(a.y1)<.01||Math.abs(a.y1-s.building.l)<.01))continue;const test={x:Math.min(a.x1,a.x2)-.05,y:Math.min(a.y1,a.y2)-.05,w:Math.abs(a.x2-a.x1)+.1,l:Math.abs(a.y2-a.y1)+.1};if(!s.openings.some(q=>{const b=openingSegment(s,q);return overlap(test,{x:Math.min(b.x1,b.x2)-.05,y:Math.min(b.y1,b.y2)-.05,w:Math.abs(b.x2-b.x1)+.1,l:Math.abs(b.y2-b.y1)+.1});})){spot={wall,offset};break;}}if(spot)break;}action(()=>s.openings.push({...o,...spot}));choose('opening',id,true);toast('Ouverture ajoutée · choisissez sa façade et ses dimensions');}
function rotate(){const o=current();if(!o||u.selected.type==='opening'||u.selected.type==='zone')return;action(()=>{const w=o.w;o.w=o.l;o.l=w;if(u.selected.type==='object')o.rotation=((o.rotation||0)+90)%360;});}
function duplicate(){const o=current();if(!o||u.selected.type==='zone')return;const copy=structuredClone(o),type=u.selected.type;copy.id=uid();if(type==='opening')copy.offset+=copy.w+.15;else{copy.x+=.3;copy.y+=.3;if(type==='room')copy.name+=' (copie)';}action(()=>{(type==='room'?s.rooms:type==='object'?s.objects:s.openings).push(copy);});choose(type,copy.id);toast('Élément dupliqué');}
function remove(){const o=current();if(!o||u.selected.type==='zone')return;const type=u.selected.type,removeNow=()=>{action(()=>{if(type==='room'){const ids=s.objects.filter(q=>q.roomId===o.id).map(q=>({id:q.id,rect:objectRect(s,q)}));for(const q of ids){const object=s.objects.find(x=>x.id===q.id);object.x=q.rect.x;object.y=q.rect.y;object.roomId=null;}s.rooms=s.rooms.filter(q=>q.id!==o.id);}else if(type==='object')s.objects=s.objects.filter(q=>q.id!==o.id);else s.openings=s.openings.filter(q=>q.id!==o.id);u.selected=null;});toast('Élément retiré · Ctrl Z pour annuler');};if(type==='room')confirmAction('Retirer cette pièce ?',`Retirer « ${esc(o.name)} » du module ? Son mobilier restera sur le plan.`,removeNow);else removeNow();}
function zoom(factor,event=null){let before=event?point(event):null;u.zoom=clamp(u.zoom*factor,.5,5);applyViewBox();if(before){const after=point(event);u.panX+=before.x-after.x;u.panY+=before.y-after.y;applyViewBox();}}
function showPopover(anchor,html){const p=$('#popover');p.innerHTML=html;p.hidden=false;const r=anchor.getBoundingClientRect();p.style.left=`${Math.max(8,Math.min(innerWidth-220,r.right-210))}px`;p.style.top=`${Math.min(innerHeight-p.offsetHeight-12,r.bottom+8)}px`;}
function exportMenu(){showPopover($('#export-button'),`<button data-export="json">${icon('file')}<span>Projet modifiable<small>JSON · sauvegarder ou transférer</small></span></button><button data-export="svg">${icon('plan')}<span>Plan vectoriel<small>SVG · net à toutes les tailles</small></span></button><button data-export="png">${icon('eye')}<span>Image du plan<small>PNG · partager votre idée</small></span></button><hr><button data-action="print">${icon('file')}<span>Récapitulatif imprimable<small>Plan, quantités & budget · PDF via imprimer</small></span></button><hr><button data-action="import">${icon('folder')}Importer un projet JSON</button><button data-action="projects">${icon('folder')}Mes projets sur cet appareil</button>`);}
const filename=()=>s.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'atelier-habitat';
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function svgExport(){const bounds={x:-1.15,y:-1.2,w:s.building.w+2.3,h:s.building.l+2.4};return `<svg xmlns="http://www.w3.org/2000/svg" width="1800" height="${Math.round(1800*bounds.h/bounds.w)}" viewBox="${bounds.x} ${bounds.y} ${bounds.w} ${bounds.h}"><rect x="${bounds.x}" y="${bounds.y}" width="${bounds.w}" height="${bounds.h}" fill="#f3f4ec"/>${plan2D(s,{...u,layer:'layout',grid:false,selected:null},true)}</svg>`;}
async function exportFile(type){$('#popover').hidden=true;if(type==='json'){download(new Blob([JSON.stringify({...s,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),filename()+'.json');toast('Projet exporté');}else if(type==='svg'){download(new Blob([svgExport()],{type:'image/svg+xml;charset=utf-8'}),filename()+'-plan.svg');toast('Plan vectoriel exporté');}else if(type==='png'){const url=URL.createObjectURL(new Blob([svgExport()],{type:'image/svg+xml'})),im=new Image();im.onload=()=>{const canvas=document.createElement('canvas');canvas.width=im.naturalWidth;canvas.height=im.naturalHeight;canvas.getContext('2d').drawImage(im,0,0);canvas.toBlob(b=>{if(b){download(b,filename()+'-plan.png');toast('Image du plan exportée');}else toast('Export impossible. Essayez le format SVG.');});URL.revokeObjectURL(url);};im.onerror=()=>{URL.revokeObjectURL(url);toast('Export impossible. Essayez le format SVG.');};im.src=url;}}
function printProject(){closeDrawers();$('#popover').hidden=true;const view=u.view;u.view='plan';renderPlan(true);requestAnimationFrame(()=>{window.print();u.view=view;renderPlan(true);});}
function projectsDialog(){save();openModal('Vos projets',`<p>Retrouvez vos variantes sur cet appareil. Pour les transférer ou les conserver ailleurs, exportez le projet en JSON.</p>${Object.entries(projects).map(([id,p])=>`<div class="project-row"><button data-project-load="${esc(id)}"><strong>${esc(p.data.name)}</strong><small>${fmt(area(p.data.building))} m² · ${fmt(area(p.data.zone))} m² habités ${id===activeId?'· projet ouvert':''}</small></button>${id!==activeId?`<button class="icon-btn" data-project-delete="${esc(id)}" title="Supprimer ce projet" aria-label="Supprimer ${esc(p.data.name)}">${icon('trash')}</button>`:'<span class="mini-tag">OUVERT</span>'}</div>`).join('')}<div class="modal-actions"><button class="btn" data-project-new="copy">${icon('copy')}Créer une variante</button><button class="btn primary" data-project-new="new">${icon('plus')}Nouveau projet</button></div>`);}
function switchProject(id){if(!projects[id])return;s=normalize(projects[id].data);activeId=id;u.selected=null;past=[];future=[];save();render(true);$('#modal').close();closeDrawers();toast('Projet ouvert');}
function newProject(copy=false){save();s=copy?structuredClone(s):defaults();s.name=copy?s.name+' — variante':'Nouveau projet';activeId=uid();u.selected=null;past=[];future=[];save();render(true);$('#modal').close();closeDrawers();renameDialog();}
function renameDialog(){openModal('Donnez un nom à votre lieu',`<label class="field"><span>Nom du projet</span><input id="rename-value" type="text" maxlength="70" value="${esc(s.name)}" autocomplete="off"></label><div class="modal-actions"><button class="btn" data-modal-close>Fermer</button><button class="btn primary" data-rename>Enregistrer</button></div>`);$('#rename-value').focus();$('#rename-value').select();}
function methods(){const C=compute(s);openModal('Des calculs lisibles, un projet à affiner',`<div class="info-note" style="margin-top:0"><div><strong>Outil d’avant-projet</strong>Les résultats servent à comparer vos idées. Les prix sont des hypothèses modifiables, sans tarif fournisseur en direct. Le plan utilise des surfaces brutes : l’épaisseur des murs et cloisons n’est pas retranchée.</div></div><h3>Isolation & quantités</h3><p>R = épaisseur en mètres / conductivité λ. Les surfaces d’ouverture sont retirées des murs. Le module inclut ses parois vers l’atelier, son plafond et son sol. La marge de coupe est appliquée aux achats et au prix des matériaux, pas aux surfaces géométriques.</p><table class="method-table"><tr><th>Surface</th><th>Nette</th><th>Avec marge ${fmt(s.thermal.waste)} %</th></tr>${[['Murs',C.walls],['Plafond',C.roof],['Sol',C.roof]].map(([t,a])=>`<tr><td>${t}</td><td>${fmt(a)} m²</td><td>${fmt(a*(1+s.thermal.waste/100))} m²</td></tr>`).join('')}</table><h3>Thermique</h3><p>Déperditions = Σ(surface × U × écart de température), auxquelles s’ajoute le renouvellement d’air : 0,34 × volume × débit en vol/h × ΔT. U = 1 / (R isolant + résistance superficielle simplifiée). Les fenêtres et les portes ont leur propre U. L’atelier, l’extérieur et le sol peuvent avoir des températures différentes. Ponts thermiques, structure existante, apports solaires et infiltrations additionnelles ne sont pas modélisés. Ce n’est ni un DPE, ni une étude réglementaire, ni un calcul de puissance de chauffage.</p><h3>Lumière naturelle & artificielle</h3><p>Le pourcentage de vitrage est un objectif de conception réglable, initialement 16,7 %. Il ne valide aucune conformité. Seule la partie de fenêtre donnant réellement sur une façade de la pièce est prise en compte. Pas de simulation d’exposition, d’ombrage ni de transmission lumineuse. Le nord affiché est un repère visuel.</p><p>Luminaires = arrondi supérieur de (surface × lux / lumens / facteur d’utilisation). Les points dessinés illustrent la quantité calculée. Les lux sont des hypothèses par usage, ajustables par pièce. Les zones non affectées du module utilisent 150 lux. Les consommations supposent tous les luminaires allumés simultanément pendant ${fmt(s.light.hours)} h/jour.</p><h3>Budget</h3><p>Acquisition + frais + isolants + parois + forfait réseaux/finitions + menuiseries + mobilier + imprévus sur les travaux. Le coût d’un meuble peut être modifié en le sélectionnant. Les cloisons partagées sont comptées une seule fois. Hors étude de structure, réfection du bâtiment, raccordements extérieurs, taxes et démarches. Les provisions n’incluent pas un devis de main-d’œuvre spécifique.</p>${warnings(C).length?`<h3>À ajuster sur ce plan</h3><ul>${warnings(C).map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}<div class="modal-actions"><button class="btn primary" data-modal-close>Revenir au projet</button></div>`);}
function guide(){openModal('Quelques gestes, beaucoup de possibilités',`<h3>1. Définissez le bâtiment</h3><p>Réglez la largeur, la longueur et la hauteur. Dimensionnez le module habitable et placez-le près d’une façade. Trois scénarios permettent de repartir rapidement.</p><h3>2. Dessinez votre quotidien</h3><p>Ajoutez vos pièces, puis le mobilier. Touchez un élément pour le sélectionner ; glissez-le pour le déplacer. Le carré dans l’angle permet de changer ses dimensions. Le bouton règle ouvre des cotes précises. Sur mobile, « Ajouter & configurer » ouvre le catalogue.</p><h3>3. Explorez les volumes</h3><p>Passez en vue en volume et glissez pour faire tourner le bâtiment. L’édition de position se fait en 2D. Les parois sont volontairement coupées pour voir l’intérieur.</p><h3>4. Ajustez le confort et les coûts</h3><p>Placez les ouvertures, testez l’isolation et les points lumineux, puis adaptez les coûts à vos devis. Les alertes en bas du plan signalent les chevauchements et votre objectif de vitrage.</p><h3>Vos raccourcis</h3><div class="keyboard-grid"><span>Sélection / déplacer la vue</span><span><kbd>V</kbd> <kbd>H</kbd></span><span>Annuler / rétablir</span><span><kbd>Ctrl Z</kbd> <kbd>Ctrl Maj Z</kbd></span><span>Tourner / dupliquer</span><span><kbd>R</kbd> <kbd>Ctrl D</kbd></span><span>Déplacer de 10 cm</span><kbd>Flèches</kbd><span>Supprimer / désélectionner</span><span><kbd>Suppr</kbd> <kbd>Échap</kbd></span><span>Zoomer / recentrer</span><span>Molette · <kbd>0</kbd></span></div><h3>Enregistrer et partager</h3><p>Les projets sont enregistrés dans ce navigateur, sur cet appareil. « Exporter » permet de récupérer le projet modifiable en JSON, un plan SVG ou PNG et un récapitulatif imprimable. Les fichiers JSON du premier configurateur restent importables.</p><div class="modal-actions"><button class="btn" data-action="methods">Calculs & hypothèses</button><button class="btn primary" data-modal-close>C’est parti</button></div>`);}
function handleAction(a){if(a==='rotate')rotate();if(a==='duplicate')duplicate();if(a==='delete')remove();if(a==='inspect'){renderInspector();$('.app').classList.remove('show-catalog');$('.app').classList.add('show-inspector');}if(a==='print')printProject();if(a==='import'){$('#popover').hidden=true;$('#import-file').click();}if(a==='projects'){$('#popover').hidden=true;projectsDialog();}if(a==='methods')methods();if(a==='overview'){openModal('Le bilan de votre projet',overview(compute(s))+thermalCard(compute(s)));}}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t){if(!e.target.closest('#popover'))$('#popover').hidden=true;return;}if(!e.target.closest('#popover')&&t.id!=='export-button'&&t.id!=='layer-button')$('#popover').hidden=true;
if(t.hasAttribute('data-close-drawer'))closeDrawers();if(t.hasAttribute('data-modal-close'))$('#modal').close();if(t.hasAttribute('data-confirm')){$('#modal').close();const fn=confirmation;confirmation=null;fn?.();}if(t.hasAttribute('data-rename')){const name=$('#rename-value').value.trim();if(name){action(()=>s.name=name);$('#modal').close();}}
if(t.dataset.step)go(t.dataset.step);if(t.dataset.go){$('#modal').close();go(t.dataset.go);}if(t.dataset.category){u.category=t.dataset.category;u.query='';renderCatalog();}if(t.dataset.comfort){u.comfort=t.dataset.comfort;u.layer=u.comfort;render();}if(t.dataset.addRoom)addRoom(t.dataset.addRoom);if(t.dataset.addObject)addObject(t.dataset.addObject);if(t.dataset.addOpening)addOpening(t.dataset.addOpening);if(t.dataset.select){const [type,id]=t.dataset.select.split(':');choose(type,id,true);}if(t.dataset.inspector){u.inspector=t.dataset.inspector;renderInspector();}if(t.dataset.view){u.view=t.dataset.view;renderPlan(true);}if(t.dataset.tool){u.tool=t.dataset.tool;renderPlan();}if(t.dataset.action)handleAction(t.dataset.action);if(t.dataset.export)exportFile(t.dataset.export);
if(t.dataset.preset)confirmAction('Repartir de ce scénario ?',`Le scénario ${t.dataset.preset} m² remplacera le plan ouvert. Vous pourrez annuler cette modification.`,()=>{action(()=>{s=preset(Number(t.dataset.preset));u.selected=null;},true);toast('Scénario chargé');});
if(t.dataset.layer){u.layer=t.dataset.layer;$('#popover').hidden=true;renderPlan();}if(t.dataset.projectLoad)switchProject(t.dataset.projectLoad);if(t.dataset.projectNew)newProject(t.dataset.projectNew==='copy');if(t.dataset.projectDelete){const id=t.dataset.projectDelete;confirmAction('Supprimer ce projet ?',`La variante « ${esc(projects[id]?.data.name||'')} » sera retirée de cet appareil.`,()=>{delete projects[id];save();projectsDialog();});}
switch(t.id){case 'undo':undo();break;case 'redo':redo();break;case 'fit':case 'fit-top':case 'zoom-value':renderPlan(true);break;case 'zoom-in':zoom(1.25);break;case 'zoom-out':zoom(.8);break;case 'export-button':exportMenu();break;case 'projects-button':projectsDialog();break;case 'project-name':renameDialog();break;case 'help-button':case 'shortcuts-button':guide();break;case 'method-button':methods();break;case 'grid-toggle':u.grid=!u.grid;renderPlan();break;case 'snap-toggle':u.snap=!u.snap;renderPlan();toast(u.snap?'Aimantation activée · pas de 10 cm':'Placement libre');break;case 'fullscreen':$('.app').classList.toggle('fullscreen');break;case 'mobile-catalog':$('.app').classList.add('show-catalog');break;case 'layer-button':showPopover(t,[['layout','Aménagement','layout'],['light','Lumière & vitrage','sun'],['thermal','Enveloppe isolée','snow']].map(([k,label,i])=>`<button data-layer="${k}" class="${u.layer===k?'active':''}">${icon(i)}${label}</button>`).join(''));break;}
});
$('#drawer-shade').addEventListener('click',closeDrawers);
document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){u.query=e.target.value;$('#catalog-items').innerHTML=catalogItems();}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.path){const path=el.dataset.path;action(()=>set(path,path==='thermal.scope'?el.value:Number(el.value)));}if(el.dataset.entityField){const o=current();if(!o)return;const key=el.dataset.entityField;action(()=>{if(key==='roomId'){const p=objectRect(s,o),r=s.rooms.find(r=>r.id===el.value);o.roomId=r?.id||null;o.x=p.x-(r?s.zone.x+r.x:0);o.y=p.y-(r?s.zone.y+r.y:0);}else o[key]=['name','type','wall','host'].includes(key)?el.value:Number(el.value);});}});
document.addEventListener('dragstart',e=>{const t=e.target.closest('[data-add-room],[data-add-object]');if(!t)return;e.dataTransfer.setData('text/plain',JSON.stringify({type:t.dataset.addRoom?'room':'object',kind:t.dataset.addRoom||t.dataset.addObject}));e.dataTransfer.effectAllowed='copy';});
$('#board').addEventListener('dragover',e=>{if(u.view==='plan'){e.preventDefault();e.dataTransfer.dropEffect='copy';}});
$('#board').addEventListener('drop',e=>{e.preventDefault();try{const d=JSON.parse(e.dataTransfer.getData('text/plain')),p=point(e);if(d.type==='room')addRoom(d.kind,p);if(d.type==='object')addObject(d.kind,p);}catch(_){toast('Choisissez un élément dans le catalogue.');}});
function point(e){const svg=$('#plan'),p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const m=svg.getScreenCTM();if(!m)return{x:0,y:0};return p.matrixTransform(m.inverse());}
const board=$('#board');
board.addEventListener('pointerdown',e=>{if(e.target.closest('button')||!e.isPrimary||e.button>0)return;const p=point(e),hit=e.target.closest('[data-entity]'),handle=e.target.closest('[data-handle]');let mode='pan';if(u.view==='volume')mode='orbit';else if(u.tool==='select'&&(hit||handle))mode=handle?'resize':'move';if(hit&&u.tool==='select'){u.selected={type:hit.dataset.entity,id:hit.dataset.id};u.inspector='selection';}else if(!handle&&mode==='pan'&&u.tool==='select'){u.selected=null;}const o=current();drag={mode,start:{x:p.x,y:p.y,clientX:e.clientX,clientY:e.clientY},orig:o?structuredClone(o):null,absolute:o&&u.selected.type==='object'?objectRect(s,o):null,before:JSON.stringify(s),panX:u.panX,panY:u.panY,yaw:u.yaw,moved:false};board.setPointerCapture(e.pointerId);e.preventDefault();renderPlan();renderInspector();});
board.addEventListener('pointermove',e=>{if(!drag)return;const dxpx=e.clientX-drag.start.clientX,dypx=e.clientY-drag.start.clientY;if(Math.hypot(dxpx,dypx)>3)drag.moved=true;if(!drag.moved)return;board.classList.add('dragging');if(drag.mode==='orbit'){u.yaw=drag.yaw+dxpx*.35;renderPlan();return;}if(drag.mode==='pan'){const m=$('#plan').getScreenCTM();u.panX=drag.panX-dxpx/m.a;u.panY=drag.panY-dypx/m.d;applyViewBox();return;}const p=point(e),dx=snap(p.x-drag.start.x),dy=snap(p.y-drag.start.y),o=current(),q=drag.orig;if(!o||!q)return;const type=u.selected.type;if(drag.mode==='resize'){const parent=type==='room'?s.zone:type==='zone'?s.building:o.roomId?s.rooms.find(r=>r.id===o.roomId):s.building;o.w=clamp(snap(q.w+dx),type==='zone'?2:type==='room'?.6:.15,parent.w-q.x);o.l=clamp(snap(q.l+dy),type==='zone'?2:type==='room'?.6:.15,parent.l-q.y);}else if(type==='opening'){const len=['north','south'].includes(o.wall)?s[o.host].w:s[o.host].l;o.offset=clamp(snap(q.offset+(['north','south'].includes(o.wall)?dx:dy)),0,len-o.w);}else if(type==='object'){const x=clamp(snap(drag.absolute.x+dx),0,s.building.w-o.w),y=clamp(snap(drag.absolute.y+dy),0,s.building.l-o.l);const r=s.rooms.find(r=>x+o.w/2>=s.zone.x+r.x&&x+o.w/2<=s.zone.x+r.x+r.w&&y+o.l/2>=s.zone.y+r.y&&y+o.l/2<=s.zone.y+r.y+r.l&&o.w<=r.w&&o.l<=r.l);o.roomId=r?.id||null;o.x=clamp(x-(r?s.zone.x+r.x:0),0,(r||s.building).w-o.w);o.y=clamp(y-(r?s.zone.y+r.y:0),0,(r||s.building).l-o.l);}else{const parent=type==='room'?s.zone:s.building;o.x=clamp(snap(q.x+dx),0,parent.w-o.w);o.y=clamp(snap(q.y+dy),0,parent.l-o.l);}if(!raf)raf=requestAnimationFrame(()=>{raf=0;renderPlan();renderMetrics();});e.preventDefault();});
function finishDrag(){if(!drag)return;const d=drag;drag=null;board.classList.remove('dragging');if(raf){cancelAnimationFrame(raf);raf=0;}if(d.mode!=='pan'&&d.mode!=='orbit'&&d.moved){s=normalize(s);if(d.before!==JSON.stringify(s)){past.push(d.before);future=[];save();}render();}else{renderPlan();renderInspector();}}
board.addEventListener('pointerup',finishDrag);board.addEventListener('pointercancel',()=>{if(drag&&drag.mode!=='orbit'&&drag.mode!=='pan')s=JSON.parse(drag.before);drag=null;board.classList.remove('dragging');render();});
board.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.08:1/1.08,e);},{passive:false});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>2e6)throw Error('Ce fichier est trop volumineux (maximum 2 Mo).');const raw=JSON.parse(await f.text()),loaded=normalize(raw);save();activeId=uid();s=loaded;past=[];future=[];u.selected=null;save();render(true);closeDrawers();toast('Projet importé dans une nouvelle variante');}catch(err){toast('Import impossible : '+err.message);}e.target.value='';});
document.addEventListener('keydown',e=>{const input=/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)||e.target.isContentEditable;if($('#modal').open){if(e.key==='Enter'&&$('#rename-value')){e.preventDefault();$('[data-rename]').click();}return;}if(input)return;const ctrl=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();if(ctrl&&k==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if(ctrl&&k==='y'){e.preventDefault();redo();return;}if(ctrl&&k==='d'){e.preventDefault();duplicate();return;}if(e.key==='Escape'){closeDrawers();$('.app').classList.remove('fullscreen');u.selected=null;$('#popover').hidden=true;render();}if(k==='r')rotate();if(k==='v'){u.tool='select';renderPlan();}if(k==='h'){u.tool='pan';renderPlan();}if(k==='0')renderPlan(true);if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();}if(k==='?')guide();if(e.key.startsWith('Arrow')&&current()&&u.selected.type!=='opening'){e.preventDefault();const d=e.shiftKey?1:.1,o=current();action(()=>{if(e.key==='ArrowLeft')o.x-=d;if(e.key==='ArrowRight')o.x+=d;if(e.key==='ArrowUp')o.y-=d;if(e.key==='ArrowDown')o.y+=d;});}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
save();render(true);
